CELLS = ['import torch\nfrom torch import nn\nfrom torch.nn import functional as F\ntorch.manual_seed(0)\nK, N, T = 5, 600, 50                  # 5 个知识点，600 个学生，每人做 50 题\np_learn = torch.tensor([0.15, 0.10, 0.20, 0.05, 0.12])   # 每做一次学会的概率\np_guess, p_slip = 0.2, 0.1            # 不会也蒙对的概率、会了却做错的概率\nknown = (torch.rand(N, K) < 0.2).float()   # 一开始就会的知识点\nsk = torch.randint(0, K, (N, T))       # 每一步做哪个知识点的题\nrs = torch.zeros(N, T)                 # 对错\ntruth = torch.zeros(N, T)              # 真实的答对概率（模型看不到）\nfor t in range(T):\n    oh = F.one_hot(sk[:, t], K).float()\n    k = (known * oh).sum(1)            # 这一题的知识点会不会\n    p = k * (1 - p_slip) + (1 - k) * p_guess\n    truth[:, t] = p\n    rs[:, t] = (torch.rand(N) < p).float()\n    learn = (torch.rand(N) < (oh * p_learn).sum(1)).float()\n    known = known + oh * (1 - known) * learn.unsqueeze(1)\nsk.shape, rs.shape, sk.dtype, rs.dtype', 'sk[0, :10], rs[0, :10]', 'def auc(y, p):\n    pairs = sorted(zip(p, y))\n    pos = sum(y); neg = len(y) - pos\n    r, i = 0, 0\n    while i < len(pairs):\n        j = i\n        while j < len(pairs) and pairs[j][0] == pairs[i][0]:\n            j += 1\n        r += (i + j + 1) / 2 * sum(1 for q in range(i, j) if pairs[q][1] == 1)\n        i = j\n    return (r - pos * (pos + 1) / 2) / (pos * neg)\n\nauc([0, 0, 1, 1], [0.1, 0.4, 0.35, 0.8]), auc([0, 1, 1, 0], [0.5, 0.5, 0.9, 0.1])', 'class DKT(nn.Module):\n    def __init__(self, K, d=32):\n        super().__init__()\n        self.K = K\n        self.emb = nn.Embedding(2 * K, d); self.lstm = nn.LSTM(d, d, batch_first=True)\n        self.drop = nn.Dropout(0.2); self.out = nn.Linear(d, K)\n\n    def encode(self, sk, rs):\n        x = self.emb(sk + self.K * rs.long()); h, _ = self.lstm(x)\n        return {"h": self.drop(h), "B": sk.shape[0]}\n\n    def readout_all(self, H, qpos):\n        return self.out(H["h"].index_select(1, qpos))\n\n    def readout(self, H, q, qpos):\n        return self.readout_all(H, qpos).gather(-1, q)\n\nmodel = DKT(K)\nmodel, sum(p.numel() for p in model.parameters())', "H = model.encode(sk[:2], rs[:2])\nqpos = torch.arange(T - 1)\nH['h'].shape, model.readout_all(H, qpos).shape, model.readout(H, sk[:2, 1:].unsqueeze(-1), qpos).shape", 'def batch_loss(model, sk, rs):\n    H = model.encode(sk, rs)\n    qpos = torch.arange(sk.shape[1] - 1)\n    logit = model.readout(H, sk[:, 1:].unsqueeze(-1), qpos).squeeze(-1)\n    y = rs[:, 1:]\n    return F.binary_cross_entropy_with_logits(logit, y), logit\n\nl, logit = batch_loss(model, sk[:4], rs[:4])\nl.shape, logit.shape, 0.6 < l.item() < 0.8', 'perm = torch.randperm(N)\nte, va, tr = perm[:120], perm[120:168], perm[168:]   # 20% 测试，剩下的 10% 验证，其余训练（和论文的比例一样）\nlen(tr), len(va), len(te)', "def eval_bce(model, idx):\n    model.eval()\n    with torch.no_grad():\n        l, logit = batch_loss(model, sk[idx], rs[idx])\n    return l.item(), torch.sigmoid(logit)\n\ndef train_kt(model, epochs=15, lr=2e-3, BS=32):\n    opt = torch.optim.Adam(model.parameters(), lr=lr)\n    best, best_ep, best_state = float('inf'), -1, None\n    for ep in range(epochs):\n        model.train(); p = tr[torch.randperm(len(tr))]\n        for i in range(0, len(p), BS):\n            b = p[i:i + BS]\n            loss, _ = batch_loss(model, sk[b], rs[b])\n            opt.zero_grad(); loss.backward()\n            nn.utils.clip_grad_norm_(model.parameters(), 5.0); opt.step()\n        vb, _ = eval_bce(model, va)\n        if vb < best:\n            best = vb; best_ep = ep\n            best_state = {k: v.detach().clone() for k, v in model.state_dict().items()}\n        print(f'epoch {ep + 1:2d}  验证集 BCE {vb:.4f}' + ('  ← 目前最好' if best_ep == ep else ''))\n    model.load_state_dict(best_state)\n    model.eval()\n    return best_ep\n\ntorch.manual_seed(1)\nmodel = DKT(K)\nt = __import__('time').time() if False else None\nbest_ep = train_kt(model)", "tb, p_te = eval_bce(model, te)\ny = rs[te][:, 1:].reshape(-1).tolist()\nprint('测试集 BCE', round(tb, 4), ' AUC', round(auc(y, p_te.reshape(-1).tolist()), 4))\nprint('知道真实掌握状态时的 AUC（上限）', round(auc(y, truth[te][:, 1:].reshape(-1).tolist()), 4))"]
